            return MTRStartInvokeInteraction(typedBridge, request, exchangeManager, session, successCb, failureCb, self->_endpoint,
                timedInvokeTimeoutMs, invokeTimeout);
        });
    std::move(*bridge).DispatchAction(self.device);
}

