                TypeInfo::DecodableType value;
                CHIP_ERROR err = clusterStateCacheContainer.cppClusterStateCache->Get<TypeInfo>(path, value);
                if (err == CHIP_NO_ERROR) {
                    successCb(bridge, value);
                }
                return err;
            }
            return CHIP_ERROR_NOT_FOUND;
